import{c as i,a1 as l,V as d,j as c,g as t,n as o,o as s,m as a,a7 as h}from"./chunks/framework.BQhatpAZ.js";const P=JSON.parse('{"title":"规范","description":"TOON 规范导览：章节结构、合规性检查清单、媒体类型和版本管理。","frontmatter":{"description":"TOON 规范导览：章节结构、合规性检查清单、媒体类型和版本管理。"},"headers":[],"relativePath":"zh/reference/spec.md","filePath":"zh/reference/spec.md","lastUpdated":1783486305000}'),p={name:"zh/reference/spec.md"};function m(r,e,b,f,u,g){const n=l("CopyOrDownloadAsMarkdownButtons");return d(),c("div",null,[e[1]||(e[1]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /zh/reference/spec.md for this page in Markdown format",-1)),e[2]||(e[2]=t("h1",{id:"规范",tabindex:"-1"},[o("规范 "),t("a",{class:"header-anchor",href:"#规范","aria-label":'Permalink to "规范"'},"​")],-1)),s(n),e[3]||(e[3]=a('<p><a href="https://github.com/toon-format/spec" target="_blank" rel="noreferrer">TOON 规范</a> 是实现编码器、解码器和校验器的权威参考。它定义了具体语法、规范性的编码/解码行为，以及严格模式下的校验规则。</p><p>如果只是<em>使用</em> TOON，无需阅读本页；本页主要面向实现者和贡献者。如果你想学习如何使用 TOON，请从 <a href="/zh/guide/getting-started.html">快速开始</a> 指南入手。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>TOON 规范已经稳定，但仍在持续演进中。规范并非一成不变，欢迎通过贡献内容或分享反馈来参与其后续发展。</p></div><h2 id="当前版本" tabindex="-1">当前版本 <a class="header-anchor" href="#当前版本" aria-label="Permalink to &quot;当前版本&quot;">​</a></h2>',4)),t("p",null,[t("strong",null,"规范 v"+h(r.$spec.version),1),e[0]||(e[0]=o("（2026-05-20）是当前已发布的工作草案。该版本已足够稳定并可作为实现依据，但尚未定稿；详情请参阅规范中的 “Status of This Document” 部分。",-1))]),e[4]||(e[4]=a('<h2 id="媒体类型与文件扩展名" tabindex="-1">媒体类型与文件扩展名 <a class="header-anchor" href="#媒体类型与文件扩展名" aria-label="Permalink to &quot;媒体类型与文件扩展名&quot;">​</a></h2><p>规范在 <a href="https://github.com/toon-format/spec/blob/main/SPEC.md#17-iana-considerations" target="_blank" rel="noreferrer">§17</a> 中定义了临时媒体类型和文件扩展名：</p><ul><li><strong>媒体类型：</strong> <code>text/toon</code>（临时，尚未在 IANA 注册；仅支持 UTF-8）</li><li><strong>文件扩展名：</strong> <code>.toon</code></li></ul><p>TOON 文档始终使用 UTF-8 编码和 LF（<code>\\n</code>）换行符；可选的 <code>charset</code> 参数如果存在，其值为 <code>utf-8</code>。</p><h2 id="规范导览" tabindex="-1">规范导览 <a class="header-anchor" href="#规范导览" aria-label="Permalink to &quot;规范导览&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#1-terminology-and-conventions" target="_blank" rel="noreferrer">§1 术语与约定</a>： 定义了“缩进层级”“生效分隔符”“严格模式”等关键术语，以及 RFC2119 关键词（MUST、SHOULD、MAY）。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#2-data-model" target="_blank" rel="noreferrer">§2 数据模型</a>： 规定了 JSON 数据模型（对象、数组、基本类型）、数组和对象的顺序要求，以及规范数字格式（位于 <code>[1e-6, 1e21)</code> 范围内或为零的值使用规范十进制；超出该范围允许使用指数记法）。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#3-encoding-normalization-reference-encoder" target="_blank" rel="noreferrer">§3 编码规范化</a>： 定义了非 JSON 类型（Date、BigInt、NaN、Infinity、undefined 等）在编码前应如何规范化。编码器实现者应重点阅读这一节。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#4-decoding-interpretation-reference-decoder" target="_blank" rel="noreferrer">§4 解码解释</a>： 规定了解码器如何将文本标记映射为宿主语言中的值（带引号的字符串、不带引号的基本类型，以及解析数字时对前导零的处理）。在参考实现中，解码器默认启用严格模式（<code>strict = true</code>）；严格模式错误见 §14。</p><h3 id="语法规则" tabindex="-1">语法规则 <a class="header-anchor" href="#语法规则" aria-label="Permalink to &quot;语法规则&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#5-concrete-syntax-and-root-form" target="_blank" rel="noreferrer">§5 具体语法与根形式</a>： 定义了 TOON 这种面向行、基于缩进的表示法，并说明如何判断根值是对象、数组还是基本类型。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#6-header-syntax-normative" target="_blank" rel="noreferrer">§6 首部语法</a>： 给出数组首部的规范性 ABNF 语法：<code>key[N&lt;delim?&gt;]{fields}:</code>。该节规定了方括号片段、分隔符符号和字段列表。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#7-strings-and-keys" target="_blank" rel="noreferrer">§7 字符串与键</a>： 完整的引号规则（字符串何时必须加引号）、合法转义序列（仅包括 <code>\\\\</code>、<code>\\&quot;</code>、<code>\\n</code>、<code>\\r</code>、<code>\\t</code>，以及用于其他 U+0000–U+001F 控制字符的 <code>\\uXXXX</code>），以及键的编码要求。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#8-objects" target="_blank" rel="noreferrer">§8 对象</a>： 对象字段编码（<code>key: value</code>）、嵌套规则、键顺序保留，以及空对象处理。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#9-arrays" target="_blank" rel="noreferrer">§9 数组</a>： 涵盖所有数组形式：基本类型数组（内联）、对象数组（表格化）、混合数组/非一致数组（列表），以及数组的数组。该节还包括表格化检测要求。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#10-objects-as-list-items" target="_blank" rel="noreferrer">§10 作为列表项的对象</a>： 列表项中对象的缩进规则（第一个字段位于连字符所在行），包括第一个字段为表格化数组时的规范模式（首部位于连字符所在行，行数据缩进深度为 +2，同级字段缩进深度为 +1）。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#11-delimiters" target="_blank" rel="noreferrer">§11 分隔符</a>： 分隔符作用域（文档级分隔符与生效分隔符）、基于分隔符的引号处理，以及逗号、制表符、竖线分隔符的解析规则。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#12-indentation-and-whitespace" target="_blank" rel="noreferrer">§12 缩进与空白</a>： 编码要求（一致的空格缩进、缩进中不允许使用制表符、无行尾空格/换行符）以及解码规则（严格和非严格缩进处理）。</p><h3 id="合规性与校验" tabindex="-1">合规性与校验 <a class="header-anchor" href="#合规性与校验" aria-label="Permalink to &quot;合规性与校验&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#13-conformance-and-options" target="_blank" rel="noreferrer">§13 合规性与选项</a>： 定义了合规类型（编码器、解码器、校验器）、标准化选项以及合规检查清单。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#134-key-folding-and-path-expansion" target="_blank" rel="noreferrer">§13.4 键折叠与路径展开</a>： 可选的编码器特性（键折叠）和解码器特性（路径展开），用于折叠/展开带点号的路径；该节还包含深度合并语义，以及严格/非严格模式下的冲突解决方式。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#14-strict-mode-errors-and-diagnostics-authoritative-checklist" target="_blank" rel="noreferrer">§14 严格模式下的错误与诊断</a>： 严格模式下各类错误的<strong>权威检查清单</strong>：数组数量与宽度不匹配（§14.1）、语法和结构错误（§14.2）、路径展开冲突（§14.3），以及重复的同级键（§14.4）。</p><h3 id="实现指导" tabindex="-1">实现指导 <a class="header-anchor" href="#实现指导" aria-label="Permalink to &quot;实现指导&quot;">​</a></h3><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#15-security-considerations" target="_blank" rel="noreferrer">§15 安全考量</a>： 与安全相关的注入风险、引号规则和严格模式检查。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#16-internationalization" target="_blank" rel="noreferrer">§16 国际化</a>： Unicode 处理，以及不受语言环境影响的数字文本格式。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#17-iana-considerations" target="_blank" rel="noreferrer">§17 IANA 考量</a>： 媒体类型注册计划及临时状态。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#18-versioning-and-extensibility" target="_blank" rel="noreferrer">§18 版本管理与可扩展性</a>： 规范的演进方式：主版本和次版本变更，以及可扩展性策略。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#19-intellectual-property-considerations" target="_blank" rel="noreferrer">§19 知识产权考量</a>： 规范的许可和知识产权条款。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-f-host-type-normalization-examples-informative" target="_blank" rel="noreferrer">附录 F：宿主类型规范化示例</a>： 为 Go、JavaScript、Python、Rust 和 Java 实现提供参考说明，介绍各语言特有类型的规范化方式。</p><p><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-c-test-suite-and-compliance-informative" target="_blank" rel="noreferrer">附录 C：测试套件与合规性</a>： 位于 <a href="https://github.com/toon-format/spec/tree/main/tests" target="_blank" rel="noreferrer">github.com/toon-format/spec/tree/main/tests</a> 的参考测试套件，可用于校验各实现。</p><h2 id="规范章节一览" tabindex="-1">规范章节一览 <a class="header-anchor" href="#规范章节一览" aria-label="Permalink to &quot;规范章节一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>何时阅读</th></tr></thead><tbody><tr><td>§1–4</td><td>数据模型、规范化、解码</td><td>实现编码器/解码器时</td></tr><tr><td>§5–6</td><td>语法、首部、根形式</td><td>实现解析器时</td></tr><tr><td>§7</td><td>字符串、键、引号、转义</td><td>实现字符串处理时</td></tr><tr><td>§8–10</td><td>对象、数组、列表项</td><td>实现结构编码时</td></tr><tr><td>§11–12</td><td>分隔符、缩进、空白</td><td>实现格式化与校验时</td></tr><tr><td>§13</td><td>合规性、选项、键折叠/路径展开</td><td>实现选项与特性时</td></tr><tr><td>§14</td><td>严格模式错误</td><td>实现校验器时</td></tr><tr><td>§15–16</td><td>安全、国际化</td><td>运行和部署时的注意事项</td></tr><tr><td>§17–19</td><td>IANA、版本管理、知识产权</td><td>生态与许可</td></tr></tbody></table><h2 id="合规性检查清单" tabindex="-1">合规性检查清单 <a class="header-anchor" href="#合规性检查清单" aria-label="Permalink to &quot;合规性检查清单&quot;">​</a></h2><p>规范包含三份合规性检查清单：</p><h3 id="编码器检查清单-§13-1-↗-spec-md" tabindex="-1">编码器检查清单（§13.1） <sup><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#131-encoder-conformance-checklist" target="_blank" rel="noreferrer">↗ SPEC.md</a></sup> <a class="header-anchor" href="#编码器检查清单-§13-1-↗-spec-md" aria-label="Permalink to &quot;编码器检查清单（§13.1） &lt;sup&gt;[↗ SPEC.md](https://github.com/toon-format/spec/blob/main/SPEC.md#131-encoder-conformance-checklist)&lt;/sup&gt;&quot;">​</a></h3><p>关键要求：</p><ul><li>生成 UTF-8 编码、LF 换行符的输出</li><li>使用一致的缩进（默认 2 个空格，不使用制表符）</li><li>在带引号的字符串中转义 <code>\\\\</code>、<code>\\&quot;</code>、<code>\\n</code>、<code>\\r</code>、<code>\\t</code>，对其他任意 U+0000–U+001F 控制字符使用 <code>\\uXXXX</code>；拒绝未配对的 UTF-16 代理码位</li><li>对包含生效分隔符、冒号或结构性字符的字符串加引号</li><li>输出与实际数量一致的数组长度 <code>[N]</code></li><li>保留对象键的顺序</li><li>按 §2 输出数字（对于 <code>[1e-6, 1e21)</code> 范围内或为零的值使用规范十进制；超出该范围允许使用指数记法）</li><li>将 <code>-0</code> 转换为 <code>0</code>，将 <code>NaN</code>/±Infinity 转换为 <code>null</code></li><li>以小写字面量形式输出布尔值和 null（<code>true</code>、<code>false</code>、<code>null</code>）</li><li>不得包含行尾空格或末尾换行符</li><li>启用 <code>keyFolding=&quot;safe&quot;</code> 时，折叠必须遵循 §13.4： <ul><li>只折叠合法标识符片段的键（字母/数字/下划线，不含点号），</li><li>不得与现有的同级键产生冲突，</li><li>不得折叠需要加引号的片段。</li></ul></li><li>设置了 <code>flattenDepth</code> 时，折叠必须在配置的片段数处停止（§13.4）。</li></ul><h3 id="解码器检查清单-§13-2-↗-spec-md" tabindex="-1">解码器检查清单（§13.2） <sup><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#132-decoder-conformance-checklist" target="_blank" rel="noreferrer">↗ SPEC.md</a></sup> <a class="header-anchor" href="#解码器检查清单-§13-2-↗-spec-md" aria-label="Permalink to &quot;解码器检查清单（§13.2） &lt;sup&gt;[↗ SPEC.md](https://github.com/toon-format/spec/blob/main/SPEC.md#132-decoder-conformance-checklist)&lt;/sup&gt;&quot;">​</a></h3><p>关键要求：</p><ul><li>按 §6 解析数组首部（长度、分隔符、字段）</li><li>仅使用生效分隔符拆分内联数组和表格化行</li><li>只使用合法转义对带引号的字符串进行反转义</li><li>为不带引号的值判定类型：true/false/null → 布尔值/null，数字 → 数字，其他 → 字符串</li><li>在 <code>strict=true</code> 时强制执行严格模式规则</li><li>保留数组顺序和对象键顺序</li><li>启用 <code>expandPaths=&quot;safe&quot;</code> 时，按 §13.4 将带点号的键展开为嵌套对象： <ul><li>按 <code>.</code> 拆分，仅当所有片段均为合法标识符片段时才进行展开，</li><li>对重叠的路径进行深度合并（对象 + 对象），</li><li>不对数组执行按元素的合并。</li></ul></li><li>当 <code>expandPaths=&quot;safe&quot;</code> 且 <code>strict=true</code>（默认）时，遇到任何展开冲突都必须报错（§14.3）。</li><li>当 <code>expandPaths=&quot;safe&quot;</code> 且 <code>strict=false</code> 时，必须采用确定性的“最后写入者优先”（LWW）冲突解决方式（§13.4）。</li></ul><h3 id="校验器检查清单-§13-3-↗-spec-md" tabindex="-1">校验器检查清单（§13.3） <sup><a href="https://github.com/toon-format/spec/blob/main/SPEC.md#133-validator-conformance-checklist" target="_blank" rel="noreferrer">↗ SPEC.md</a></sup> <a class="header-anchor" href="#校验器检查清单-§13-3-↗-spec-md" aria-label="Permalink to &quot;校验器检查清单（§13.3） &lt;sup&gt;[↗ SPEC.md](https://github.com/toon-format/spec/blob/main/SPEC.md#133-validator-conformance-checklist)&lt;/sup&gt;&quot;">​</a></h3><p>校验器应当验证：</p><ul><li>结构性合规（首部、缩进、列表标记）</li><li>空白不变式（无行尾空格/换行符）</li><li>首部与行数据之间的分隔符一致性</li><li>实际数组长度与声明的 <code>[N]</code> 相符</li><li>所有严格模式要求（包括启用时的路径展开冲突）</li></ul><h2 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h2><p>规范使用语义化版本（主版本号、次版本号）：</p><ul><li><strong>主版本</strong>（例如 v2 → v3）：破坏性变更，与之前版本不兼容</li><li><strong>次版本</strong>（例如 v3.1 → v3.2）：澄清说明、新增要求，或向后兼容的补充内容</li></ul><p>详细的版本历史请参阅 <a href="https://github.com/toon-format/spec/blob/main/SPEC.md#appendix-d-document-changelog-informative" target="_blank" rel="noreferrer">附录 D：文档变更日志</a>。</p><h2 id="为规范做贡献" tabindex="-1">为规范做贡献 <a class="header-anchor" href="#为规范做贡献" aria-label="Permalink to &quot;为规范做贡献&quot;">​</a></h2><p>该规范由社区在 <a href="https://github.com/toon-format/spec" target="_blank" rel="noreferrer">github.com/toon-format/spec</a> 上维护。我们欢迎各种形式的贡献：报告歧义或错误、提出澄清说明和示例、向参考测试套件添加测试用例，或讨论边界情况和规范性行为。你的反馈有助于推动这一格式的发展。</p>',50))])}const _=i(p,[["render",m]]);export{P as __pageData,_ as default};
